-- Q1 [Lineweaver-Burk (Double-Reciprocal) Plots] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Lineweaver-Burk (Double-Reciprocal) Plots', 'A biochemist studying an enzyme wants to linearize her initial-velocity data so that she can read off \(V_{max}\) and \(K_m\) from a straight line rather than fitting a hyperbola. She decides to construct a Lineweaver-Burk plot of her data. On such a double-reciprocal plot, which two quantities are graphed against each other?', '[{"label": "A", "text": "\\(1/v_0\\) on the y-axis versus \\(1/[S]\\) on the x-axis"}, {"label": "B", "text": "\\(v_0\\) on the y-axis versus \\([S]\\) on the x-axis"}, {"label": "C", "text": "\\(v_0\\) on the y-axis versus \\(1/[S]\\) on the x-axis"}, {"label": "D", "text": "\\(1/v_0\\) on the y-axis versus \\([S]\\) on the x-axis"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because the Lineweaver-Burk plot is the double-reciprocal transform of the Michaelis-Menten equation, in which the reciprocal of the initial velocity is plotted against the reciprocal of the substrate concentration. The reference states that ''the graphs are referred to as Lineweaver-Burk plots, where plots of 1/v vs 1/S are straight lines with slope m = KM/VM, and y-intercept b = 1/VM'' (line 27475), and labels the plot ''Lineweaver-Burk (double reciprocal): 1/vo s 1/So'' (line 27482). Because both axes are reciprocals, the curved Michaelis-Menten hyperbola becomes a straight line from which \(V_{max}\) (from the \(1/v_0\) intercept, \(1/V_{max}\)) and \(K_m\) (from the \(1/[S]\) intercept, \(-1/K_m\)) can be estimated (line 26959). (Choice A) is correct: plotting \(1/v_0\) versus \(1/[S]\) is the defining double-reciprocal, linear Lineweaver-Burk transform. (Choice B) is wrong because \(v_0\) versus \([S]\) is the untransformed Michaelis-Menten plot, which the reference describes as a ''nonlinear hyperbolic fit'' (line 27462) and as ''Michaelis-Menten: vo vs So'' (line 27482) — a hyperbola, not the linear Lineweaver-Burk plot. (Choice C) is wrong because plotting \(v_0\) (not its reciprocal) against \(1/[S]\) takes the reciprocal of only one axis; the Lineweaver-Burk plot is a double-reciprocal plot, so the y-axis must be \(1/v_0\), not \(v_0\) (line 27475). (Choice D) is wrong because plotting \(1/v_0\) against \([S]\) (not \(1/[S]\)) again reciprocates only one axis; the double-reciprocal plot requires the x-axis to be \(1/[S]\), not \([S]\) (line 27475). This is a Knowledge of Scientific Concepts and Principles question because you must recall that the Lineweaver-Burk plot is the double-reciprocal transform that graphs \(1/v_0\) against \(1/[S]\).', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 45)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'confusing the hyperbolic MM plot with its linear transform' FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', 'single-reciprocal hybrid axis' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'single-reciprocal hybrid axis' FROM q;

-- Q2 [Lineweaver-Burk (Double-Reciprocal) Plots] medium skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Lineweaver-Burk (Double-Reciprocal) Plots', 'A researcher analyzing an enzyme''s initial-velocity data constructs a Lineweaver-Burk plot, graphing \(1/v_0\) against \(1/[S]\) to obtain a straight line. To estimate the enzyme''s maximum velocity, the researcher should determine the value that corresponds to which feature of this line?', '[{"label": "A", "text": "The x-intercept, which equals \\(-1/K_m\\)"}, {"label": "B", "text": "The y-intercept, which equals \\(1/V_{max}\\)"}, {"label": "C", "text": "The slope, which equals \\(K_m/V_{max}\\)"}, {"label": "D", "text": "The y-intercept, which equals \\(1/K_m\\)"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because, on a Lineweaver-Burk (double-reciprocal) plot of \(1/v_0\) versus \(1/[S]\), the line has a ''slope m = KM/VM, and y-intercept b = 1/VM'' (LibreTexts Biochemistry, line 27475-27476). Because the y-intercept equals \(1/V_{max}\), reading that intercept and taking its reciprocal directly yields the maximum velocity, which is why the researcher should use the y-intercept. (Choice A) is incorrect: the x-intercept equals \(-1/K_m\), since the text states ''the x-intercepts (-1/KM)'' (line 27846); this value gives \(K_m\), not \(V_{max}\). (Choice B) is correct: the y-intercept equals \(1/V_{max}\) (''y-intercept b = 1/VM'', line 27476), so its reciprocal gives the maximum velocity. (Choice C) is incorrect: the slope equals \(K_m/V_{max}\) (''slope m = KM/VM'', line 27475), a composite quantity from which \(V_{max}\) cannot be obtained without also knowing \(K_m\). (Choice D) is incorrect: \(1/K_m\) is not a feature of this plot at all (the x-intercept is the negative reciprocal, \(-1/K_m\), per line 27846), and even the magnitude relates to \(K_m\), not \(V_{max}\). This is a Knowledge of Scientific Concepts and Principles question because you must recall the algebraic identities that the slope and intercepts of a Lineweaver-Burk plot represent.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 60)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'adjacent_fact', 'x-intercept/Km confusion' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'slope/intercept confusion' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'right-axis/wrong-parameter swap' FROM q;

-- Q3 [Lineweaver-Burk (Double-Reciprocal) Plots] medium skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Lineweaver-Burk (Double-Reciprocal) Plots', 'A researcher analyzing an enzyme''s initial-velocity data converts a Michaelis-Menten curve into a Lineweaver-Burk (double-reciprocal) plot of \(1/v_0\) versus \(1/[S]\) and reads the value where the fitted line crosses the horizontal axis. Which kinetic quantity does this x-intercept most directly correspond to?', '[{"label": "A", "text": "\\(1/V_{max}\\)"}, {"label": "B", "text": "\\(+1/K_m\\)"}, {"label": "C", "text": "\\(-1/K_m\\)"}, {"label": "D", "text": "\\(-1/V_{max}\\)"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because on a Lineweaver-Burk (double-reciprocal) plot of \(1/v_0\) versus \(1/[S]\), the line crosses the x-axis at \(-1/K_m\). The textbook explicitly identifies ''the x-intercept (–1/KM)'' on the Lineweaver-Burk plot (libretexts-biochemistry.txt, line 27755), and elsewhere states that ''-1/Km, the x-intercept on the plot'' shifts as kinetic parameters change (line 28122). This x-intercept is distinct from the y-intercept, which the same source gives as ''y-intercept b = 1/VM'' (lines 27475–27476). (Choice A) is incorrect: \(1/V_{max}\) is the y-intercept of the Lineweaver-Burk plot, not the x-intercept, because the text states the ''y-intercept b = 1/VM'' (lines 27475–27476). (Choice B) is incorrect: the x-intercept is the negative quantity \(-1/K_m\), not \(+1/K_m\); the source specifies ''the x-intercept (–1/KM)'' with a negative sign (line 27755). (Choice C) is correct: the x-intercept equals \(-1/K_m\), exactly as the text labels ''the x-intercept (–1/KM)'' (line 27755) and ''-1/Km, the x-intercept on the plot'' (line 28122). (Choice D) is incorrect: \(-1/V_{max}\) is not an intercept of this plot; the \(V_{max}\)-related intercept is the y-intercept equal to the positive value \(1/V_{max}\) (lines 27475–27476). This is a Knowledge of Scientific Concepts and Principles question because you must recall the standard Lineweaver-Burk intercept identities, specifically that the x-intercept of the double-reciprocal plot equals \(-1/K_m\).', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 60)
  RETURNING id
)
