  SELECT id, 'A', 'misconception', 'read-the-intercept-directly trap' FROM q
  UNION ALL
  SELECT id, 'B', 'scale_unit_error', 'magnitude error' FROM q
  UNION ALL
  SELECT id, 'C', 'scale_unit_error', 'order-of-magnitude error' FROM q;

-- Q5 [Lineweaver-Burk (Double-Reciprocal) Plots] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Lineweaver-Burk (Double-Reciprocal) Plots', 'A researcher characterizing a purified enzyme constructs a Lineweaver-Burk (double-reciprocal) plot of \(1/v_0\) versus \(1/[S]\) and measures the x-intercept to be \(-1/K_m = -0.5\ \text{mM}^{-1}\). Based on this single linear transformation, which value most likely represents the enzyme''s Michaelis constant \(K_m\)?', '[{"label": "A", "text": "2 mM"}, {"label": "B", "text": "0.5 mM"}, {"label": "C", "text": "1 mM"}, {"label": "D", "text": "-2 mM"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because on a Lineweaver-Burk (double-reciprocal) plot, the x-intercept equals \(-1/K_m\), so \(K_m\) is recovered by taking the negative reciprocal of that intercept. The source states that for the double-reciprocal plot, the relevant linear parameters identify ''the x-intercept (–1/KM)'' (line 27755), and likewise that ''the x-intercepts (-1/KM)'' shift on the plot (line 27846). Setting \(-1/K_m = -0.5\ \text{mM}^{-1}\) gives \(1/K_m = 0.5\ \text{mM}^{-1}\), so \(K_m = 1/0.5 = 2\ \text{mM}\); because \(K_m\) is a substrate concentration it must be a positive value with units of concentration. (Choice A) is correct: inverting \(0.5\ \text{mM}^{-1}\) yields \(K_m = 2\ \text{mM}\), the positive Michaelis constant. (Choice B) is wrong: 0.5 mM is the bare magnitude of the x-intercept value treated as if it were \(K_m\) directly, but \(K_m\) is the reciprocal of that magnitude, not the magnitude itself, since the x-intercept reports \(-1/K_m\) rather than \(K_m\) (line 27755). (Choice C) is wrong: 1 mM does not satisfy \(-1/K_m = -0.5\ \text{mM}^{-1}\) (that would require an x-intercept of \(-1\ \text{mM}^{-1}\)); it reflects a miscalculation rather than the negative-reciprocal relationship the x-intercept encodes (line 27846). (Choice D) is wrong: -2 mM has the correct magnitude but retains the negative sign of the x-intercept; \(K_m\) is a positive substrate concentration, so the sign of the intercept must not be carried into the final answer (line 27755). This is a Scientific Reasoning and Problem Solving question because you must apply the double-reciprocal intercept relationship to compute \(K_m\) through a negative-reciprocal transformation while correctly handling sign and units.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 75)
  RETURNING id
)
