-- Q25 [Local Conditions: Temperature, pH & Salinity] hard skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Local Conditions: Temperature, pH & Salinity', 'An enzyme placed in a buffer of very high salt concentration loses nearly all of its catalytic activity, yet gel analysis confirms that its polypeptide chain has not been cut into shorter fragments and that its molecular weight is unchanged. Which structural level of the enzyme is most likely disrupted under these conditions?', '[{"label": "A", "text": "Its primary structure, as the peptide-bond sequence that defines the chain is disrupted"}, {"label": "B", "text": "Its tertiary and quaternary structure, as the non-covalent interactions maintaining the folded 3D shape are disrupted"}, {"label": "C", "text": "Its primary structure, as the covalent peptide backbone is hydrolyzed at multiple points"}, {"label": "D", "text": "Its primary structure, as the order of amino acids in the chain is rewritten into a new sequence"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because high salt concentration is a denaturing agent that disrupts the non-covalent interactions holding a protein in its folded three-dimensional shape, not the covalent bonds of the backbone. LibreTexts states that clues to ''what stabilizes the tertiary structure of a native protein can be gained by subjecting proteins to agents that unfold or denature proteins,'' and that ''such agents include pH extremes, high concentrations of some salt solutions or organic solvents, and temperature extremes'' (lines 14702-14703). The folded state is held together by ''noncovalent forces'' that ''cause a protein to fold spontaneously to a unique 3D structure,'' namely the ''noncovalent interactions (ion-ion, H bonds, van der Waals)'' (lines 14698-14699, 14706); the tertiary structure is defined as ''the overall 3D structure of the protein'' (line 11058), and quaternary structure is the ''assembly of two or more protein subunits'' held by ''noncovalent interactions and disulfide bonds'' (lines 11029-11030). The text further separates this kind of denaturation from covalent change by directing students to ''recognize the difference between enzyme denaturation (via extremes of pH and temperature) and irreversible covalent modification'' (lines 27747-27748), and the observation that the chain is not cut and its molecular weight is unchanged confirms the covalent peptide bonds are intact. (Choice A) is incorrect: the primary structure is defined as the protein''s ''unique linear sequence of amino acids'' joined by ''covalent peptide bonds'' (lines 6368, 6379), and these covalent bonds are not broken by salt, which acts only on non-covalent interactions, so the primary structure is preserved. (Choice B) is correct: high salt denatures the enzyme by disrupting the non-covalent interactions that maintain the tertiary and quaternary (3D folded) structure, exactly the structures the text says such agents probe (lines 14702-14703, 11058, 11029-11030). (Choice C) is incorrect: hydrolyzing the ''covalent peptide bonds'' (line 6379) would cut the chain and lower its molecular weight, but the stem specifies the chain is not cut and the molecular weight is unchanged, and denaturation is explicitly distinguished from covalent modification (lines 27747-27748). (Choice D) is incorrect: the amino-acid sequence is fixed by covalent peptide bonds and is ''determined by the genomic DNA'' rather than rewritten by a change in the solution, so altering salt concentration cannot reorder the primary sequence (lines 6368, 6379). This is a Scientific Reasoning and Problem Solving question because you must apply the distinction between covalent peptide bonds (primary structure) and the non-covalent interactions that stabilize the folded 3D structure to interpret why a high-salt environment abolishes activity while leaving the intact, full-length chain unchanged.', 'hard', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 2, 120)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'misconception', NULL FROM q
  UNION ALL
  SELECT id, 'C', 'partial_truth', NULL FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', NULL FROM q;
